"""Final policy-safe report; no production mutation or retry."""
import json,hashlib,datetime,collections
from pathlib import Path
O=Path(__file__).parent;root=Path('/home/gvasend/app/kge-forge')
load=lambda n:json.loads((O/n).read_bytes())
sha=lambda b:hashlib.sha256(b).hexdigest()
def save(n,x):(O/n).write_text(json.dumps(x,sort_keys=True,indent=2))
pin=load('CURRENT_PIN.json');pub=json.loads(Path(pin['path']).read_bytes());assert sha(Path(pin['path']).read_bytes())==pin['sha256']
f=load('TERMINAL_EVIDENCE.json');rec=load('INDEPENDENT_TERMINAL_RECOVERY.json');status=load('FRESH_TERMINAL_OPERATOR_STATUS.json')
assert f['classification']=='INTERRUPTED_NO_EFFECTS' and f['reconciled'] and all(v==0 for v in f['counts'].values())
assert rec['lifecycle_state']=='CANCELLED' and rec['ownership'] is None and not rec['handoff_eligible'] and not rec['reconciliation_required']
assert status['lifecycle_state']=='CANCELLED' and status['ownership']=='RELEASED' and status['architectural_state']=='QUIESCENT'
audit=Path(pub['audit']);rows=[json.loads(x) for x in audit.read_bytes().splitlines()];ctrl=[r for r in rows if r.get('schema')=='E1-RUN-CONTROL-1'];budgets=load('BUDGET_HISTORY.json')
assert sha(audit.read_bytes())==f['audit_sha256']
marker=json.loads((Path(pub['private_run_root'])/'ONE_ATTEMPT_STARTED').read_bytes())
exhaust=next(r for r in ctrl if r['event']=='budget_exhausted');assert exhaust['details']['budget']=='no_progress'
files={}
for n in ('src/kge_forge/__init__.py','src/kge_forge/context','tests/context','docs/implementation/E1-WP-001.md'):
 p=root/n
 for x in ([p] if p.is_file() else p.rglob('*') if p.is_dir() else []):
  if x.is_file() and not x.is_symlink():files[str(x.relative_to(root))]=sha(x.read_bytes())
base=load('PRODUCT_BASELINE.json')['files'];changes={k:{'before':base.get(k),'after':files.get(k)} for k in set(base)|set(files) if base.get(k)!=files.get(k)};assert not changes
save('PRODUCT_EFFECTS.json',{'implementation_produced':False,'authoritative_repository_changes':changes,'knowledge_changes':[],'governed_tests':[],'executions':[],'work_package_exercised':False})
save('FIRST_ACTION_MILESTONE.json',{'milestone':'FIRST_REAL_PROGRAMMER_ACTION_REQUEST','status':'NOT_REACHED','model_cycles':f['model_cycles'],'model_requests':0,'ActionRequests':0,'reason':'HARD_NO_SUBSTANTIVE_PROGRESS_BUDGET_DURING_PRE_MODEL_VALIDATION'})
save('ACCEPTANCE_COVERAGE.json',{f'WP1-AC{i:02}':{'result':'NOT_EXERCISED','evidence':'No model request, ActionRequest, execution or implementation effect'} for i in range(1,10)})
history=load('HISTORICAL_BASELINE.json');ledger='/tmp/kge-forge-e1-invocations.jsonl';assert all(sha(Path(p).read_bytes())==h for p,h in history.items() if p!=ledger)
data=Path(ledger).read_bytes();prefix=b'';tail=None
for line in data.splitlines(keepends=True):
 prefix+=line
 if sha(prefix)==history[ledger]:tail=data[len(prefix):];break
assert tail is not None;extra=[json.loads(x) for x in tail.splitlines()]
assert [x['event'] for x in extra]==['invocation_reserved','invocation_released']
assert extra[0]['authorization_id']==pub['authorization_id'] and extra[0]['reservation_id']==extra[1]['reservation_id'] and extra[1]['terminal_event_id']==f['last_event_id']
save('HISTORICAL_PRESERVATION.json',{'result':'PASS','immutable_files_verified':len(history)-1,'ledger_original_prefix_preserved':True,'new_typed_ledger_events':extra,'r8_r9_r10_r11_unchanged':True,'Run1_unchanged':True})
observations=[json.loads(p.read_bytes()) for p in sorted((O/'operator_status').glob('*.json'))]
summary={'live_snapshots':len(observations),'freshness_counts':dict(collections.Counter(v.get('freshness','UNKNOWN') for v in observations)),'lifecycle_counts':dict(collections.Counter(v.get('lifecycle_state','UNKNOWN') for v in observations)),'unknown_reasons':dict(collections.Counter(v.get('uncertainty','unspecified') for v in observations if v.get('freshness')=='UNKNOWN')),'final_fresh_status':status,'observer_ended_before_separate_cancellation_recovery':True}
save('OPERATOR_OBSERVABILITY.json',summary)
spans=load('PHASE_TIMING.json')['spans'];tops=[s for s in spans if s['depth']==0]
timeline=[{'event':'DRIVER_START','wall_time':marker['wall_time'],'certainty':'KNOWN'}]
for n in ('IMMEDIATE_PRE_ISSUANCE.json','INACTIVE_ISSUANCE.json','INDEPENDENT_INACTIVE_RECOVERY.json','ACTIVE_COMMIT.json','INDEPENDENT_ACTIVE_RECOVERY.json','ORCHESTRATION_STOP.json','CANCELLATION_UNRESOLVED.json','RECOVERY_UNRESOLVED.json','RECOVERY_CANCELLATION.json'):
 d=load(n);timeline.append({'event':n,'wall_time':d['wall_time'],'certainty':'KNOWN_REPORT_TIME_AFTER_OPERATION'})
timeline.append({'event':'HARD_NO_PROGRESS_STOP','wall_time':exhaust['wall_time'],'certainty':'KNOWN_DURABLE_BUDGET_EVENT'})
timeline.append({'event':'INDEPENDENT_TERMINAL_RECOVERY_RESULT_PERSISTED','wall_time':(O/'INDEPENDENT_TERMINAL_RECOVERY.json').stat().st_mtime,'certainty':'DERIVED_FILESYSTEM_RESULT_MTIME'})
for t in timeline:t.update(elapsed_from_driver=t['wall_time']-marker['wall_time'],EDT=datetime.datetime.fromtimestamp(t['wall_time'],datetime.timezone(datetime.timedelta(hours=-4))).isoformat(timespec='milliseconds'))
timeline.sort(key=lambda t:t['wall_time']);save('TIMELINE.json',timeline)
original=load('ORCHESTRATION_SCRIPTS.json');assert all(sha((O/n).read_bytes())==h for n,h in original.items())
save('EXECUTED_SCRIPT_HASHES.json',{p.name:sha(p.read_bytes()) for p in O.glob('*.py')})
result={'invocation':pub['authorization_id'],'disposition':'CANCELLED','classification':'INTERRUPTED_NO_EFFECTS','trigger':'HARD_BUDGET_STOP','breached_budget':'no_progress','breach_seconds':exhaust['details']['value'],'independent_terminal_recovery':'PASS','ownership':'RELEASED','ExecutionScope':'NONE','QUIESCENT':True,'admission':'DURABLY_CLOSED','uncertainty':None,'counts':f['counts'],'model_cycles':f['model_cycles'],'first_action_milestone':'NOT_REACHED','implementation_produced':False,'repository_changes':0,'knowledge_changes':0,'tests':0,'acceptance_coverage':'WP1-AC01..09 NOT_EXERCISED','token_usage':'USAGE_UNKNOWN','provider_processing':'NO_REQUEST_INITIATED','provider_wait_seconds':0,'budget_warnings':f['budget_warnings'],'budget_exhaustions':f['budget_exhaustions'],'budgets_changed':False,'automatic_cancellation':'FAILED_CLOSED_TELEMETRY_BLOCKED_CANCELLATION_RECONSTRUCTION','separate_typed_cancellation_recovery':'PASS_NO_ADMISSION_REOPENING','activation_event':f['activation_event_id'],'reservation_id':extra[0]['reservation_id'],'terminal_event':f['last_event_id'],'audit_sha256':f['audit_sha256'],'release_authority':pub['release_authority'],'OperationalContextId':pub['operational_identities']['OperationalContextId'],'authority_expansion_requests':[],'automatic_retry':False,'replacement_attempt_created':False,'human_intervention':'No additional engineering decision or host restart; agent invoked cancellation-only recovery after automatic reconciliation failed; sandbox execution approvals used','Experiment1_acceptance':'NOT_ESTABLISHED'}
save('FINAL_RESULT.json',result)
lines=['# E1 Run-2 r12 terminal report','','`CANCELLED / INTERRUPTED_NO_EFFECTS` — independent terminal recovery PASS. Trigger: HARD_BUDGET_STOP (no substantive progress).','','r12 completed INACTIVE issuance, independent INACTIVE recovery, activation with exact ownership, independent ACTIVE recovery and dispatcher entry. It did not reach a model request or ActionRequest. E1-WP-001 was not exercised. No implementation, repository or canonical knowledge change, governed test or ExecutionScope occurred. FIRST_REAL_PROGRAMMER_ACTION_REQUEST was not reached. WP1-AC01..09 remain NOT_EXERCISED.','','## Budget and timing','',f'The unchanged 300-second no-progress hard threshold fired at {exhaust["details"]["value"]:.6f}s during pre-model validation. There were {f["budget_warnings"]} soft warnings and {f["budget_exhaustions"]} hard exhaustion event. No substantive-progress event occurred. All elapsed pre-handoff work was controller work, not model/provider processing. Token accounting is USAGE_UNKNOWN; no provider request or usage response exists. No token ceiling is claimed.','','| Closed outer timing span | Seconds |','|---|---:|']
for s in tops:
 if not s['name'].startswith('attempt_history_'):lines.append(f'| {s["name"]} | {s["seconds"]:.3f} |')
lines+=['',f'Independent ACTIVE recovery took {load("INDEPENDENT_ACTIVE_RECOVERY.json")["seconds"]:.3f}s including reconstruction outside its inner span. Cancellation-only recovery took {load("RECOVERY_CANCELLATION.json")["seconds"]:.3f}s; independent terminal recovery took {rec["seconds"]:.3f}s. The final 7.774-second validation span ended by budget interruption, not successful validation. Pre-issuance production preflight took 26.556s. PHASE_TIMING.json retains all nested spans; summing nested spans would double-count. TIMELINE.json distinguishes durable timestamps from the terminal result-file persistence time.','','## Cancellation anomaly and resolution','','Automatic cancellation encountered BudgetExceeded during ActivationTransaction.cancel → lifecycle reconstruction → dispatch verification → instrumented attempt-history decision. The telemetry sink was already closed, so its span admission check blocked cancellation reconstruction. The orchestration wrapper also attempted to construct RunControl on durably closed admission and failed. The initial terminal recovery correctly refused ACTIVE ownership with closed admission. These failures are preserved in ORCHESTRATION_STOP.json, CANCELLATION_UNRESOLVED.json and INDEPENDENT_TERMINAL_RECOVERY_FAILURE.json.','','The agent then invoked the unchanged typed cancellation operation in a separate cancellation-only recovery session with the optional telemetry sink unset. It checked exact ACTIVE ownership, closed admission, zero model/provider requests and actions, and absence of scopes/uncertainty; reconstructed the governed host, requested interruption, and called ActivationTransaction.cancel. No effect admission, handoff or model continuation was enabled. Only r12 ownership was released. No runtime implementation or budget was changed. Independent recovery now establishes CANCELLED, no ownership, no reconciliation required and no handoff eligibility.','','## Observability and practical outcome','',f'Live projection captured {len(observations)} snapshots: {summary["freshness_counts"]}. Authoritative lifecycle observations were {summary["lifecycle_counts"]}. UNKNOWN causes: {summary["unknown_reasons"]}. The original observer stopped after failed automatic recovery; a separate fresh terminal projection establishes CANCELLED / RELEASED / QUIESCENT. Live observability was intermittent during authority/audit reconstruction; this limitation is preserved, not represented as uninterrupted healthy status.','','The actual issued/owned path exceeded the earlier prepared preflight timings and consumed the complete no-progress allowance before provider entry. Successful warm pre-issuance timing did not guarantee practical end-to-end dispatch startup. The budget stopped the invocation correctly, but automatic cancellation composition and actual-path validation cost require Architect assessment before another attempt. No remediation was implemented during this run.','','## Exact durable identities','',f'- Invocation: `{pub["authorization_id"]}`',f'- Release: `{pub["release_authority"]}`',f'- Context: `{pub["operational_identities"]["OperationalContextId"]}`',f'- Activation: `{f["activation_event_id"]}`',f'- Reservation: `{extra[0]["reservation_id"]}`',f'- Cancellation: `{f["last_event_id"]}`',f'- Final audit SHA-256: `{f["audit_sha256"]}`','','EVENT_TRACE.json and ACTION_TRACE.json provide policy-safe event identity/hash traceability to the private audit. No protected model text was retained by the wrapper. BUDGET_HISTORY.json and USAGE.json preserve all available budget/usage evidence.','','## Preservation and intervention','',f'{len(history)-1} immutable historical files verified unchanged. The ownership ledger retains its exact original prefix and appends only r12 reservation/release. r8, r9, r10, r11 and Run-1 evidence remain unchanged. The applied r12 authority records remain applied; the invocation is terminal and must not be reused.','','No authority-expansion request, tool denial/correction, model interruption, host restart or human engineering decision occurred. The recovery intervention was cancellation-only orchestration after automatic cancellation failed; sandbox execution approvals were used. There is no unresolved invocation uncertainty after independent terminal recovery. No r13 was created and no retry occurred. Experiment 1 PASS and KGE Forge v0.1 acceptance are not established.','']
(O/'REPORT.md').write_text('\n'.join(lines))
save('EVIDENCE_HASHES.json',{str(p.relative_to(O)):sha(p.read_bytes()) for p in O.rglob('*') if p.is_file() and '__pycache__' not in str(p) and p.name!='EVIDENCE_HASHES.json'})
print(json.dumps({'result':result,'timing':[(s['name'],s['seconds']) for s in tops if not s['name'].startswith('attempt_history_')],'status':summary['freshness_counts']}))
